CREATE TABLE stock (
  item text PRIMARY KEY,
  qty int NOT NULL CHECK (qty >= 0)
);
INSERT INTO stock VALUES
  ('Шолом', 5), ('Каска', 3);

BEGIN;
UPDATE stock SET qty = qty - 2
WHERE item = 'Шолом';
UPDATE stock SET qty = qty - 10
WHERE item = 'Каска';
SELECT * FROM stock;
COMMIT;

SELECT * FROM stock ORDER BY item;

BEGIN;
UPDATE stock SET qty = qty - 2
WHERE item = 'Шолом';
SAVEPOINT before_helmet;
UPDATE stock SET qty = qty - 10
WHERE item = 'Каска';
ROLLBACK TO SAVEPOINT before_helmet;
UPDATE stock SET qty = qty - 1
WHERE item = 'Каска';
COMMIT;

SELECT * FROM stock ORDER BY item;

